GimCorpus.put(471,0,[[1,9,"אבל אם יעמוד מלך משאר ישראל תפסק המלכות וכו'. א\"א זה סותר מה שאמר למעלה ולא המלכות בלבד וכו'. א\"ו כן הוא אילו היה ירבעם מלך כשר ובניו כשרים לא היתה מלכות פוסקת מזרעו אבל היתה שניה למלכות בית דוד כגון קיסר ופלג קיסר:",1,0],[3,2,"לא ירבה לו נשים וכו' עד הכל שמונה עשרה. א\"א זה אי אפשר שהרי היו לדוד שש נשים ופלגשים כשאמר לו נתן הנביא ואוסיפה לך כהנה וכהנה נמצא י\"ח חוץ מן הפלגשים הן:",1,0],[6,1,"אין עושין מלחמה עם אדם בעולם וכו'. א\"א אין שואלין למלחמת הרשות אלא שיהיו למס:",1,0],[6,4,"אבל שבעה עממין ועמלק וכו'. א\"א זה שבוש אלא שיכול לומר השלימו לקבל המצות:",1,0],[6,5,"אם כן מפני מה הערימו יושבי גבעון וכו'. א\"א כל זה שבוש שלא שלח להם יהושע להשלים אלא עד שלא עברו את הירדן אבל אחר מיכן אין מקבלין אותן:",1,0],[7,1,"אחד מלחמת מצוה וכו'. א\"א אפשר להיות זה לענין אל ירך לבבכם אבל לענין השאר החוזרים מעורכי המלחמה לא נאמר אלא למלחמת הרשות אבל לא למלחמת מצוה והכי איתא בגמרא:",1,0],[9,1,"וכן היה הדבר בכל העולם וכו' עד והוסיף תפלה לפנות היום. א\"א כן היה ראוי לומר והוא התפלל שחרית והפריש מעשר (ויצחק הוסיף תפלה אחרת) עכ\"ל:",1,0],[9,4,"וכן אם הרג כו' מה שאין כן בישראל. א\"א קשיא ליה אבנר. עכ\"ל:",1,0],[9,11,"אחד האבר ואחד הבשר כו'. א\"א ומן העוף:",1,0],[9,11,"אבל העוף יראה לי וכו'. א\"א נ\"ל שזה טעות סופר וראוי להיות אבל השרץ:",2,0],[11,3,"אל יעלה על דעתך וכו'. א\"א והלא בן כוזיבא היה אומר אנא הוא מלכא משיחא ושלחו חכמים לבדקו אי מורח ודאין או לא וכיון דלא עביד הכי קטלוהו:",1,0],[12,1,"אל יעלה על הלב שבימות המשיח כו' עד משלים. א\"א והלא כתוב בתורה והשבתי חיה רעה מן הארץ:",1,0]]);
